    session_set_cookie_params(['lifetime'=>(int)($config['admin_session_seconds']??28800),'httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax']);
